<script>
  const redHighlight = document.getElementById('redHighlight');
  const redCard = document.getElementById('redCard');
  const editor = document.getElementById('editor');
  const details = document.getElementById('statsDetails');
  const statsToggle = document.getElementById('statsToggle');

  function toggleRed() {
    redHighlight.classList.toggle('hidden-red');
  }
  redCard.addEventListener('click', toggleRed);
  redHighlight.addEventListener('click', function () {
    if (redHighlight.classList.contains('hidden-red')) toggleRed();
  });

  statsToggle.addEventListener('click', function () {
    details.classList.add('open');
    statsToggle.classList.add('hidden');
  });
  document.getElementById('showFewer').addEventListener('click', function () {
    details.classList.remove('open');
    statsToggle.classList.remove('hidden');
  });

  document.getElementById('writeTab').addEventListener('click', function () {
    editor.querySelectorAll('.yellow, .red, .blue, .purple').forEach(el => el.classList.add('hidden-red'));
    this.classList.add('active');
    document.getElementById('editTab').classList.remove('active');
  });
  document.getElementById('editTab').addEventListener('click', function () {
    editor.querySelectorAll('.hidden-red').forEach(el => el.classList.remove('hidden-red'));
    this.classList.add('active');
    document.getElementById('writeTab').classList.remove('active');
  });
  document.getElementById('menuButton').addEventListener('click', function () {
    this.textContent = this.textContent.includes('Menu') ? 'Menu  •  Save  •  Load' : 'Menu ⌄';
  });
</script>
